(function(root){'use strict';
const KEY='albion-craft-history-v1',clone=x=>JSON.parse(JSON.stringify(x)),id=()=>root.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),finite=(v)=>typeof v==='number'&&Number.isFinite(v),nonnegative=v=>finite(v)&&v>=0;
function create(storage){let data={version:1,batches:[],deals:[]};const raw=storage.getItem(KEY);if(raw){try{data=JSON.parse(raw);if(data?.version!==1||!Array.isArray(data.batches)||!Array.isArray(data.deals)||data.batches.length>1000||data.deals.length>3000)throw Error();const ids=new Set();for(const b of data.batches){if(!b||typeof b.uid!=='string'||ids.has(b.uid)||!['europe','west','east'].includes(b.server)||!Number.isFinite(Date.parse(b.date))||typeof b.item!=='string'||!nonnegative(b.unitCost)||!Number.isInteger(b.quantity)||b.quantity<1||!Number.isInteger(b.remaining)||b.remaining<0||b.remaining>b.quantity)throw Error();ids.add(b.uid);}const deals=new Set();for(const d of data.deals){if(!d||typeof d.uid!=='string'||deals.has(d.uid)||!Number.isFinite(Date.parse(d.date))||!finite(d.profit)||!Number.isInteger(d.quantity)||d.quantity<1||d.batch&&!ids.has(d.batch))throw Error();deals.add(d.uid);}}catch{throw Error('История крафтов повреждена. Исходные записи сохранены; запись временно недоступна.');}}
function commit(next){storage.setItem(KEY,JSON.stringify(next));data=next;}
function addBatch(value){if(data.batches.length>=1000)throw Error('История содержит 1000 партий.');const b={uid:id(),date:new Date().toISOString(),...clone(value)},qty=Number(b.quantity),cost=Number(b.totalCost);if(!Number.isInteger(qty)||qty<1||qty>1e9||!Number.isFinite(cost)||cost<0||!['europe','west','east'].includes(b.server)||!b.item||!Number.isFinite(Date.parse(b.date)))throw Error('Проверьте количество, сервер и себестоимость партии.');b.quantity=qty;b.remaining=qty;b.totalCost=cost;b.unitCost=cost/qty;b.sold=0;const next=clone(data);next.batches.push(b);commit(next);return clone(b);}
function addDeal(value){if(data.deals.length>=3000)throw Error('История содержит 3000 сделок.');const d={uid:id(),date:new Date().toISOString(),...clone(value)};if(!Number.isInteger(d.quantity)||d.quantity<1||!finite(d.profit)||!nonnegative(d.unitCost)||!nonnegative(d.price)||!nonnegative(d.fees)||!Number.isFinite(Date.parse(d.date)))throw Error('Некорректная сделка.');const next=clone(data);if(d.batch){const b=next.batches.find(b=>b.uid===d.batch);if(!b||b.server!==d.server||b.item!==d.item||b.quality!==d.quality)throw Error('Сделка не соответствует партии.');if(d.quantity>b.remaining)throw Error('Для сделки не хватает остатка партии.');if(Math.abs(d.unitCost-b.unitCost)>1e-8)throw Error('Себестоимость партии изменилась. Пересчитайте сделку.');b.remaining-=d.quantity;b.sold=b.quantity-b.remaining;}next.deals.push(d);commit(next);return clone(d);}
function undoDeal(uid){const next=clone(data),d=next.deals.find(d=>d.uid===uid);if(!d)throw Error('Сделка не найдена.');if(d.batch){const b=next.batches.find(b=>b.uid===d.batch);b.remaining+=d.quantity;b.sold=b.quantity-b.remaining;}next.deals=next.deals.filter(x=>x.uid!==uid);commit(next);}
return {snapshot:()=>clone(data),addBatch,addDeal,undoDeal};}
const api={KEY,create};root.CraftLedgerMath=api;if(typeof module!=='undefined')module.exports=api;
if(root.localStorage)try{root.CraftLedger=create(root.localStorage)}catch(error){root.CraftLedgerError=error.message;}
})(typeof window!=='undefined'?window:globalThis);
